def rle(s):
    if not s:
        return ""
    result = []
    count = 1
    for char in s[1:]:
        if char == s[0]:
            count += 1
        else:
            result.append(f"{s[0]}{count}")
            count = 1
    result.append(f"{s[0]}{count}")
    return "".join(result)

def merge(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    while i < len(a):
        result.append(a[i])
        i += 1
    while j < len(b):
        result.append(b[j])
        j += 1
    return result
